    FX.impactFrame(c, W, H, 760, GROUND - 60, f === F_HERO + 1 ? SAGE : PAL.navy, f === F_HERO + 1 ? PAL.hi : SAGE, 600 + f, { lines: f === F_HERO + 1, R: 560 });
